package ch.piiwii.euroscan;

import android.app.*;import android.content.*;import android.graphics.Color;import android.graphics.Typeface;import android.graphics.drawable.GradientDrawable;import android.net.Uri;import android.os.Bundle;import android.provider.MediaStore;import android.text.InputType;import android.view.*;import android.view.inputmethod.InputMethodManager;import android.widget.*;
import com.google.mlkit.vision.common.InputImage;import com.google.mlkit.vision.text.TextRecognition;import com.google.mlkit.vision.text.TextRecognizer;import com.google.mlkit.vision.text.latin.TextRecognizerOptions;
import org.json.*;import java.text.*;import java.util.*;import java.util.concurrent.*;

public class MainActivity extends Activity {
    private static final int CAMERA=1001,PURPLE=Color.rgb(42,22,92),ORANGE=Color.rgb(246,165,0),BG=Color.rgb(247,247,251),GREEN=Color.rgb(22,142,90),RED=Color.rgb(190,45,45);
    private LinearLayout root,gridsBox;private EditText dateEdit;private Uri photoUri;private final List<GridRow> rows=new ArrayList<>();private final ExecutorService worker=Executors.newSingleThreadExecutor();private final ResultsRepository repo=new ResultsRepository();private HistoryStore history;
    @Override public void onCreate(Bundle b){super.onCreate(b);history=new HistoryStore(this);home();}@Override protected void onDestroy(){worker.shutdownNow();super.onDestroy();}
    private void page(String title,String sub){ScrollView sc=new ScrollView(this);sc.setFillViewport(true);root=new LinearLayout(this);root.setOrientation(LinearLayout.VERTICAL);root.setPadding(dp(18),dp(18),dp(18),dp(30));root.setBackgroundColor(BG);sc.addView(root,new ScrollView.LayoutParams(-1,-2));setContentView(sc);LinearLayout h=box(PURPLE,22,18);h.addView(txt(title,28,Color.WHITE,true));h.addView(gap(5));h.addView(txt(sub,14,Color.rgb(228,222,245),false));root.addView(h,lp(-1,-2,0,0,0,18));}
    private void home(){page("EuroScan CH","Scanne ton ticket EuroMillions et contrôle chaque grille.");LinearLayout d=card();TextView dt=txt("Charge le dernier tirage pour afficher les numéros gagnants.",16,Color.DKGRAY,false);d.addView(txt("Dernier tirage",20,PURPLE,true));d.addView(gap(8));d.addView(dt);Button refresh=btn("Actualiser le dernier tirage",ORANGE,Color.BLACK);d.addView(gap(12));d.addView(refresh);root.addView(d,lp(-1,-2,0,0,0,18));refresh.setOnClickListener(v->latest(dt,refresh));Button scan=btn("📷  Scanner un ticket",PURPLE,Color.WHITE),manual=btn("✍  Saisir un ticket",Color.WHITE,PURPLE),hist=btn("🕘  Historique",Color.rgb(232,230,240),PURPLE);manual.setBackground(stroke(PURPLE,Color.WHITE,16));root.addView(scan,lp(-1,dp(58),0,0,0,11));root.addView(manual,lp(-1,dp(56),0,0,0,11));root.addView(hist,lp(-1,dp(54),0,0,0,18));root.addView(txt("EuroScan CH n'est pas affiliée à EuroMillions, Swisslos ou la Loterie Romande. Le ticket original et la validation de l'opérateur font foi.",12,Color.GRAY,false));scan.setOnClickListener(v->camera());manual.setOnClickListener(v->editor(new TicketParser.ParsedTicket(),"Saisie manuelle"));hist.setOnClickListener(v->history());}
    private void latest(TextView out,Button b){b.setEnabled(false);out.setText("Chargement…");worker.execute(()->{try{DrawResult d=repo.latest();runOnUiThread(()->{out.setText(drawLine(d)+(d.exactSwissPrizes?"\nCotes CHF suisses détectées.":"\nMontants exacts non associés : l'app les signalera comme estimations."));b.setEnabled(true);});}catch(Exception e){runOnUiThread(()->{out.setText("Impossible de charger le tirage. Vérifie la connexion Internet.");b.setEnabled(true);});}});}
    private void camera(){try{ContentValues c=new ContentValues();c.put(MediaStore.Images.Media.DISPLAY_NAME,"euroscan_"+System.currentTimeMillis()+".jpg");c.put(MediaStore.Images.Media.MIME_TYPE,"image/jpeg");if(android.os.Build.VERSION.SDK_INT>=29)c.put(MediaStore.Images.Media.RELATIVE_PATH,"Pictures/EuroScanCH");photoUri=getContentResolver().insert(MediaStore.Images.Media.EXTERNAL_CONTENT_URI,c);Intent i=new Intent(MediaStore.ACTION_IMAGE_CAPTURE);i.putExtra(MediaStore.EXTRA_OUTPUT,photoUri);i.addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION|Intent.FLAG_GRANT_WRITE_URI_PERMISSION);startActivityForResult(i,CAMERA);}catch(Exception e){toast("Impossible d'ouvrir l'appareil photo.");}}
    @Override protected void onActivityResult(int req,int result,Intent data){super.onActivityResult(req,result,data);if(req==CAMERA&&result==RESULT_OK&&photoUri!=null)ocr(photoUri);}
    private void ocr(Uri uri){page("Lecture du ticket","Reconnaissance de la date, des numéros et des étoiles…");root.addView(new ProgressBar(this),lp(-1,dp(70),0,18,0,8));root.addView(txt("Analyse en cours…",16,Color.DKGRAY,false));try{InputImage im=InputImage.fromFilePath(this,uri);TextRecognizer r=TextRecognition.getClient(TextRecognizerOptions.DEFAULT_OPTIONS);r.process(im).addOnSuccessListener(t->{r.close();editor(TicketParser.parse(t.getText()),"Ticket scanné");}).addOnFailureListener(e->{r.close();editor(new TicketParser.ParsedTicket(),"Lecture à corriger manuellement");toast("Lecture automatique insuffisante.");});}catch(Exception e){editor(new TicketParser.ParsedTicket(),"Lecture à corriger manuellement");}}
    private void editor(TicketParser.ParsedTicket p,String origin){page("Vérifier le ticket",origin+" — corrige les champs si nécessaire avant le contrôle.");rows.clear();root.addView(txt("Date du tirage",15,PURPLE,true));dateEdit=new EditText(this);dateEdit.setText(p.date==null?lastDraw():p.date);dateEdit.setHint("AAAA-MM-JJ");dateEdit.setTextSize(18);dateEdit.setSingleLine();dateEdit.setPadding(dp(14),dp(10),dp(14),dp(10));dateEdit.setBackground(round(Color.WHITE,12));root.addView(dateEdit,lp(-1,dp(52),0,5,0,18));LinearLayout tr=new LinearLayout(this);tr.setGravity(Gravity.CENTER_VERTICAL);TextView gt=txt("Grilles",20,PURPLE,true);Button add=small("+ Ajouter");tr.addView(gt,new LinearLayout.LayoutParams(0,-2,1));tr.addView(add);root.addView(tr,lp(-1,-2,0,0,0,10));gridsBox=new LinearLayout(this);gridsBox.setOrientation(LinearLayout.VERTICAL);root.addView(gridsBox);if(p.grids.isEmpty())addGrid(null);else for(TicketGrid g:p.grids)addGrid(g);add.setOnClickListener(v->addGrid(null));Button check=btn("✓  Contrôler ce ticket",ORANGE,Color.BLACK),back=btn("Retour",Color.rgb(232,230,238),PURPLE);root.addView(check,lp(-1,dp(60),0,18,0,10));root.addView(back,lp(-1,dp(50),0,0,0,0));back.setOnClickListener(v->home());check.setOnClickListener(v->check(check));}
    private void addGrid(TicketGrid g){GridRow gr=new GridRow();LinearLayout c=card(),top=new LinearLayout(this);top.setGravity(Gravity.CENTER_VERTICAL);TextView name=txt("Grille "+(rows.size()+1),16,PURPLE,true);Button del=small("Supprimer");top.addView(name,new LinearLayout.LayoutParams(0,-2,1));top.addView(del);c.addView(top);c.addView(gap(9));c.addView(txt("5 numéros",12,Color.GRAY,false));LinearLayout ns=new LinearLayout(this);for(int i=0;i<5;i++){EditText e=numBox();gr.n.add(e);ns.addView(e,new LinearLayout.LayoutParams(0,dp(48),1));if(i<4)ns.addView(gapH(5));}c.addView(ns);c.addView(gap(9));c.addView(txt("2 étoiles",12,Color.GRAY,false));LinearLayout ss=new LinearLayout(this);for(int i=0;i<2;i++){EditText e=numBox();gr.s.add(e);ss.addView(e,new LinearLayout.LayoutParams(0,dp(48),1));if(i==0)ss.addView(gapH(6));}c.addView(ss);if(g!=null){for(int i=0;i<5;i++)gr.n.get(i).setText(String.valueOf(g.numbers.get(i)));for(int i=0;i<2;i++)gr.s.get(i).setText(String.valueOf(g.stars.get(i)));}rows.add(gr);gridsBox.addView(c,lp(-1,-2,0,0,0,10));del.setOnClickListener(v->{if(rows.size()==1){toast("Il faut au moins une grille.");return;}int x=rows.indexOf(gr);rows.remove(gr);gridsBox.removeViewAt(x);renumber();});}
    private void renumber(){for(int i=0;i<gridsBox.getChildCount();i++){View v=gridsBox.getChildAt(i);if(v instanceof LinearLayout){LinearLayout c=(LinearLayout)v;if(c.getChildCount()>0&&c.getChildAt(0) instanceof LinearLayout){LinearLayout t=(LinearLayout)c.getChildAt(0);if(t.getChildCount()>0&&t.getChildAt(0) instanceof TextView)((TextView)t.getChildAt(0)).setText("Grille "+(i+1));}}}}
    private void check(Button b){hideKeyboard();String date=TicketParser.normalizeDate(dateEdit.getText().toString().trim());if(!date.matches("20\\d{2}-\\d{2}-\\d{2}")){toast("Date invalide. Format : AAAA-MM-JJ");return;}List<TicketGrid> gs=new ArrayList<>();for(int i=0;i<rows.size();i++){TicketGrid g=rows.get(i).grid();if(g==null){toast("Vérifie la grille "+(i+1)+".");return;}gs.add(g);}b.setEnabled(false);b.setText("Contrôle en cours…");worker.execute(()->{try{DrawResult d=repo.fetch(date);runOnUiThread(()->result(d,gs));}catch(Exception e){runOnUiThread(()->{b.setEnabled(true);b.setText("✓  Contrôler ce ticket");toast("Résultat introuvable pour cette date ou connexion indisponible.");});}});}
    private void result(DrawResult d,List<TicketGrid> gs){page("Résultat du ticket","Tirage "+d.date+" — "+drawLine(d));DecimalFormat f=new DecimalFormat("#,##0.00");double total=0;boolean estimate=false;StringBuilder hist=new StringBuilder();for(int i=0;i<gs.size();i++){TicketGrid g=gs.get(i);int n=d.matchingNumbers(g),s=d.matchingStars(g);String key=n+"+"+s;Double prize=d.prizeFor(n,s);boolean jackpot=n==5&&s==2,exact=d.exactSwissPrizes&&d.chfPrizes.containsKey(key);LinearLayout c=card();c.addView(txt("Grille "+(i+1)+"  ·  "+g.compact(),15,PURPLE,true));c.addView(gap(6));c.addView(txt(n+" numéro"+(n>1?"s":"")+" + "+s+" étoile"+(s>1?"s":""),15,Color.DKGRAY,false));c.addView(gap(5));if(prize==null&&!jackpot){c.addView(txt("Aucun gain",18,Color.GRAY,true));hist.append("G").append(i+1).append(": 0 CHF; ");}else if(prize!=null){total+=prize;if(!exact)estimate=true;c.addView(txt("CHF "+f.format(prize)+(exact?"":" · estimation"),20,exact?GREEN:ORANGE,true));hist.append("G").append(i+1).append(": ").append(f.format(prize)).append(exact?" CHF; ":" CHF estimés; ");}else{estimate=true;c.addView(txt("Jackpot potentiel — montant à valider officiellement",18,RED,true));hist.append("G").append(i+1).append(": jackpot potentiel; ");}root.addView(c,lp(-1,-2,0,0,0,10));}LinearLayout t=box(estimate?Color.rgb(255,246,224):Color.rgb(232,248,240),18,16);t.addView(txt(estimate?"Montant détecté / estimé":"Gain total",15,PURPLE,true));t.addView(gap(5));t.addView(txt("CHF "+f.format(total),34,estimate?ORANGE:GREEN,true));t.addView(txt(estimate?"Les montants marqués « estimation » ne sont pas officiels. Vérifie le ticket auprès de l'opérateur.":"Cotes CHF suisses récupérées pour ce tirage.",12,estimate?Color.DKGRAY:GREEN,false));root.addView(t,lp(-1,-2,0,8,0,14));Button again=btn("Scanner un autre ticket",PURPLE,Color.WHITE),h=btn("Accueil",Color.rgb(232,230,238),PURPLE);root.addView(again,lp(-1,dp(56),0,0,0,10));root.addView(h,lp(-1,dp(50),0,0,0,0));again.setOnClickListener(v->camera());h.setOnClickListener(v->home());StringBuilder all=new StringBuilder();for(TicketGrid g:gs)all.append(g.compact()).append(" | ");history.add(d.date,all.toString(),hist.toString(),total,!estimate);}
    private void history(){page("Historique","Les tickets contrôlés restent enregistrés uniquement sur ce téléphone.");JSONArray a=history.all();if(a.length()==0)root.addView(txt("Aucun ticket contrôlé pour l'instant.",16,Color.GRAY,false));for(int i=0;i<a.length();i++)try{JSONObject o=a.getJSONObject(i);LinearLayout c=card();c.addView(txt(o.optString("date"),18,PURPLE,true));c.addView(txt(o.optString("grids"),13,Color.DKGRAY,false));c.addView(gap(5));c.addView(txt(o.optString("result"),13,Color.DKGRAY,false));boolean ex=o.optBoolean("exact",false);c.addView(txt("Total : CHF "+new DecimalFormat("#,##0.00").format(o.optDouble("total"))+(ex?"":" · avec estimation"),16,ex?GREEN:ORANGE,true));root.addView(c,lp(-1,-2,0,0,0,10));}catch(Exception ignored){}Button clear=btn("Effacer l'historique",Color.WHITE,RED),h=btn("Accueil",PURPLE,Color.WHITE);clear.setBackground(stroke(RED,Color.WHITE,14));root.addView(clear,lp(-1,dp(50),0,12,0,10));root.addView(h,lp(-1,dp(50),0,0,0,0));clear.setOnClickListener(v->new AlertDialog.Builder(this).setTitle("Effacer l'historique ?").setNegativeButton("Annuler",null).setPositiveButton("Effacer",(d,w)->{history.clear();history();}).show());h.setOnClickListener(v->home());}
    private String drawLine(DrawResult d){return join(d.numbers)+"  ★ "+join(d.stars);}private String join(List<Integer> l){StringBuilder b=new StringBuilder();for(int i=0;i<l.size();i++){if(i>0)b.append(' ');b.append(String.format(Locale.US,"%02d",l.get(i)));}return b.toString();}private String lastDraw(){Calendar c=Calendar.getInstance();int d=c.get(Calendar.DAY_OF_WEEK),back=d==Calendar.FRIDAY||d==Calendar.TUESDAY?0:d==Calendar.SATURDAY?1:d==Calendar.SUNDAY?2:d==Calendar.MONDAY?3:d==Calendar.WEDNESDAY?1:d==Calendar.THURSDAY?2:0;c.add(Calendar.DAY_OF_MONTH,-back);return new SimpleDateFormat("yyyy-MM-dd",Locale.US).format(c.getTime());}
    private static class GridRow{final List<EditText> n=new ArrayList<>(),s=new ArrayList<>();TicketGrid grid(){try{List<Integer>a=new ArrayList<>(),b=new ArrayList<>();for(EditText e:n){int v=Integer.parseInt(e.getText().toString());if(v<1||v>50||a.contains(v))return null;a.add(v);}for(EditText e:s){int v=Integer.parseInt(e.getText().toString());if(v<1||v>12||b.contains(v))return null;b.add(v);}return new TicketGrid(a,b);}catch(Exception e){return null;}}}
    private EditText numBox(){EditText e=new EditText(this);e.setGravity(Gravity.CENTER);e.setTextSize(18);e.setSingleLine();e.setInputType(InputType.TYPE_CLASS_NUMBER);e.setBackground(stroke(Color.rgb(220,216,230),Color.WHITE,10));return e;}private LinearLayout card(){return box(Color.WHITE,18,16);}private LinearLayout box(int color,int radius,int pad){LinearLayout l=new LinearLayout(this);l.setOrientation(LinearLayout.VERTICAL);l.setPadding(dp(pad),dp(pad),dp(pad),dp(pad));l.setBackground(round(color,radius));return l;}private TextView txt(String s,int size,int color,boolean bold){TextView v=new TextView(this);v.setText(s);v.setTextSize(size);v.setTextColor(color);if(bold)v.setTypeface(null,Typeface.BOLD);v.setLineSpacing(0,1.08f);return v;}private Button btn(String s,int bg,int fg){Button b=new Button(this);b.setText(s);b.setTextSize(16);b.setTextColor(fg);b.setAllCaps(false);b.setTypeface(null,Typeface.BOLD);b.setBackground(round(bg,16));return b;}private Button small(String s){Button b=btn(s,Color.rgb(235,232,243),PURPLE);b.setTextSize(12);return b;}private View gap(int h){Space s=new Space(this);s.setLayoutParams(new LinearLayout.LayoutParams(1,dp(h)));return s;}private View gapH(int w){Space s=new Space(this);s.setLayoutParams(new LinearLayout.LayoutParams(dp(w),1));return s;}private LinearLayout.LayoutParams lp(int w,int h,int l,int t,int r,int b){LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(w,h);p.setMargins(dp(l),dp(t),dp(r),dp(b));return p;}private GradientDrawable round(int color,int r){GradientDrawable g=new GradientDrawable();g.setColor(color);g.setCornerRadius(dp(r));return g;}private GradientDrawable stroke(int line,int fill,int r){GradientDrawable g=round(fill,r);g.setStroke(dp(1),line);return g;}private int dp(int n){return Math.round(n*getResources().getDisplayMetrics().density);}private void toast(String s){Toast.makeText(this,s,Toast.LENGTH_LONG).show();}private void hideKeyboard(){View v=getCurrentFocus();if(v!=null)((InputMethodManager)getSystemService(INPUT_METHOD_SERVICE)).hideSoftInputFromWindow(v.getWindowToken(),0);}
}
